SET search_path TO lms, extensions;

-- Cloud rollout hardening for transactional domain workflows.
-- Backfill legacy completed progress rows so the state-machine constraint can
-- be validated, and keep internal capability helpers out of the Data API.

UPDATE lms.learner_progress
SET started_at = completed_at,
    updated_at = NOW()
WHERE status = 'completed'
  AND started_at IS NULL
  AND completed_at IS NOT NULL;

ALTER TABLE lms.learner_progress
  VALIDATE CONSTRAINT learner_progress_timestamp_state_check;

CREATE OR REPLACE FUNCTION lms.assert_rpc_actor(actor_id UUID)
RETURNS lms.users
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  actor lms.users%ROWTYPE;
  session_user_id UUID := auth.uid();
BEGIN
  IF session_user_id IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '28000';
  END IF;

  IF actor_id IS NULL OR session_user_id <> actor_id THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO actor
  FROM lms.users
  WHERE id = actor_id
    AND is_active = TRUE
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INACTIVE_ACCOUNT' USING ERRCODE = '28000';
  END IF;

  RETURN actor;
END;
$$;

REVOKE ALL ON FUNCTION lms.actor_can_manage_learner(UUID, UUID, UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION lms.actor_can_manage_event(UUID, UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION lms.assert_rpc_actor(UUID) FROM PUBLIC, anon, authenticated;;
